js:
var sws = root.querySelectorAll(".mds-toggle-rows__sw");
var out = root.querySelector(".mds-toggle-rows__count");
function sync(){
  var on = 0;
  for (var i = 0; i < sws.length; i++){ if (sws[i].getAttribute("aria-checked") === "true") on++; }
  out.textContent = on + " of " + sws.length + " on";
}
for (var i = 0; i < sws.length; i++){
  sws[i].addEventListener("click", function(){
    if (this.disabled) return;
    this.setAttribute("aria-checked", this.getAttribute("aria-checked") === "true" ? "false" : "true");
    sync();
  });
}
sync();

css:
