js:
var tracks = root.querySelectorAll(".mds-segmented-prefs__track");
for (var t = 0; t < tracks.length; t++){
  (function(track){
    var segs = track.querySelectorAll(".mds-segmented-prefs__seg");
    var hint = track.parentNode.querySelector(".mds-segmented-prefs__hint");
    for (var i = 0; i < segs.length; i++){
      (function(btn, idx){
        btn.addEventListener("click", function(){
          for (var j = 0; j < segs.length; j++){ segs[j].setAttribute("aria-checked", segs[j] === btn ? "true" : "false"); }
          track.style.setProperty("--mds-i", idx);
          hint.textContent = btn.getAttribute("data-hint");
        });
        btn.addEventListener("keydown", function(e){
          var d = e.key === "ArrowRight" ? 1 : (e.key === "ArrowLeft" ? -1 : 0);
          if (!d) return;
          e.preventDefault();
          var n = (idx + d + segs.length) % segs.length;
          segs[n].focus();
          segs[n].click();
        });
      })(segs[i], i);
    }
  })(tracks[t]);
}

