js:
var fields = root.querySelectorAll(".mds-profile-form__in, .mds-profile-form__ta, .mds-profile-form__sel");
var counter = root.querySelector(".mds-profile-form__count");
var bio = root.querySelector(".mds-profile-form__ta");
var status = root.querySelector(".mds-profile-form__status");
var btns = root.querySelectorAll(".mds-profile-form__btn");
var reset = btns[0], save = btns[1];
var start = [];
for (var i = 0; i < fields.length; i++){ start.push(fields[i].value); }
function count(){ counter.textContent = bio.value.length + " / 160"; }
function dirty(){
  var d = false;
  for (var i = 0; i < fields.length; i++){ if (fields[i].value !== start[i]) d = true; }
  reset.disabled = !d;
  save.disabled = !d;
  status.textContent = d ? "Unsaved changes" : "All changes saved";
  status.classList.toggle("mds-profile-form__status--dirty", d);
}
for (var k = 0; k < fields.length; k++){
  fields[k].addEventListener("input", function(){ count(); dirty(); });
  fields[k].addEventListener("change", dirty);
}
reset.addEventListener("click", function(){
  for (var i = 0; i < fields.length; i++){ fields[i].value = start[i]; }
  count(); dirty();
});
save.addEventListener("click", function(){
  for (var i = 0; i < fields.length; i++){ start[i] = fields[i].value; }
  dirty();
  status.textContent = "Saved just now";
});
count(); dirty();

