.mds-notify-matrix{box-sizing:border-box;background:radial-gradient(120% 90% at 0% 0%,#161B2A,#0D1017 60%);border:1px solid rgba(255,255,255,.075);border-radius:14px;padding:14px;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#E8EBF4;}
