js:
var cells = root.querySelectorAll(".mds-notify-matrix__cell");
var cols = root.querySelectorAll(".mds-notify-matrix__col");
var tally = root.querySelector(".mds-notify-matrix__tally");
function inCol(n){
  var list = [];
  for (var i = 0; i < cells.length; i++){ if (cells[i].getAttribute("data-col") === n) list.push(cells[i]); }
  return list;
}
function sync(){
  var on = 0;
  for (var i = 0; i < cells.length; i++){ if (cells[i].getAttribute("aria-checked") === "true") on++; }
  tally.textContent = on + " of " + cells.length;
}
for (var i = 0; i < cells.length; i++){
  cells[i].addEventListener("click", function(){
    this.setAttribute("aria-checked", this.getAttribute("aria-checked") === "true" ? "false" : "true");
    sync();
  });
}
for (var c = 0; c < cols.length; c++){
  cols[c].addEventListener("click", function(){
    var list = inCol(this.getAttribute("data-col"));
    var all = true;
    for (var j = 0; j < list.length; j++){ if (list[j].getAttribute("aria-checked") !== "true") all = false; }
    for (var k = 0; k < list.length; k++){ list[k].setAttribute("aria-checked", all ? "false" : "true"); }
    sync();
  });
}
sync();

