var btn = root.querySelector(".mds-danger-zone__btn");
var body = root.querySelector(".mds-danger-zone__body");
var done = root.querySelector(".mds-danger-zone__done");
var undo = root.querySelector(".mds-danger-zone__undo");
var NAME = "orbit-labs";
function check(){
  var ok = input.value.trim().toLowerCase() === NAME;
  btn.disabled = !ok;
  btn.classList.toggle("mds-danger-zone__btn--armed", ok);
}
input.addEventListener("input", check);
input.addEventListener("keydown", function(e){ if (e.key === "Enter" && !btn.disabled) btn.click(); });
btn.addEventListener("click", function(){
  if (btn.disabled) return;
  body.hidden = true;
  body.style.display = "none";
  done.hidden = false;
});
undo.addEventListener("click", function(){
  done.hidden = true;
  body.hidden = false;
  body.style.display = "";
  input.value = "";
  check();
  input.focus();
});
check();

