var opts = root.querySelectorAll(".mds-theme-picker__opt");
var sws = root.querySelectorAll(".mds-theme-picker__sw");
var foot = root.querySelector(".mds-theme-picker__foot");
var card = root.querySelector(".mds-theme-picker") || root;
var theme = "Dark", accent = "Violet";
function tell(){ foot.textContent = theme + " · " + accent + " — applies to this device only."; }
function pick(list, el){
  for (var i = 0; i < list.length; i++){ list[i].setAttribute("aria-checked", list[i] === el ? "true" : "false"); }
}
for (var i = 0; i < opts.length; i++){
  opts[i].addEventListener("click", function(){
    pick(opts, this);
    theme = this.getAttribute("data-name");
    tell();
  });
}
for (var k = 0; k < sws.length; k++){
  sws[k].addEventListener("click", function(){
    pick(sws, this);
    accent = this.getAttribute("data-name");
    card.style.setProperty("--mds-theme-picker-accent", this.style.getPropertyValue("--mds-c").trim());
    tell();
  });
}
tell();

