.mds-key-reveal{box-sizing:border-box;background:#0C0E14;border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:13px 14px;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#E8EBF4;}
.mds-key-reveal *{box-sizing:border-box;}
.mds-key-reveal__head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:4px;}
.mds-key-reveal__title{margin:0;font-size:13px;font-weight:650;}
.mds-key-reveal__env{padding:2px 7px;border-radius:5px;font-size:9px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;color:#FFC98A;background:rgba(245,178,74,.14);border:1px solid rgba(245,178,74,.32);}
