js:
var rows = root.querySelectorAll(".mds-key-reveal__row");
var reduce = false;
try { reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches; } catch (e) {}
for (var r = 0; r < rows.length; r++){
  (function(row){
    var code = row.querySelector(".mds-key-reveal__key");
    var eye = row.querySelector(".mds-key-reveal__ico");
    var copy = row.querySelector(".mds-key-reveal__copy");
    var timer = row.querySelector(".mds-key-reveal__timer");
    var bar = row.querySelector(".mds-key-reveal__fill");
    var real = code.getAttribute("data-key");
    var mask = code.getAttribute("data-mask");
    var hideT = null, scrT = null, copyT = null;
    function stop(){
      if (hideT){ clearTimeout(hideT); hideT = null; }
      if (scrT){ clearInterval(scrT); scrT = null; }
    }
    function conceal(){
      stop();
      code.textContent = mask;
      eye.setAttribute("aria-pressed", "false");
      eye.setAttribute("title", "Reveal key");
      timer.hidden = true;
      row.classList.remove("mds-key-reveal__row--open");
    }
    function reveal(){
      stop();
      eye.setAttribute("aria-pressed", "true");
      eye.setAttribute("title", "Hide key");
      row.classList.add("mds-key-reveal__row--open");
      if (reduce){
        code.textContent = real;
      } else {
        var pool = "abcdefghijkmnpqrstuvwxyz0123456789";
        var t0 = Date.now();
        scrT = setInterval(function(){
          if (!root.isConnected){ clearInterval(scrT); scrT = null; return; }
          var p = (Date.now() - t0) / 320;
          if (p >= 1){ clearInterval(scrT); scrT = null; code.textContent = real; return; }
          var solid = Math.floor(real.length * p);
          var out = "";
          for (var i = 0; i < real.length; i++){
            out += (i < solid || real.charAt(i) === "_") ? real.charAt(i) : pool.charAt(Math.floor(Math.random() * pool.length));
          }
          code.textContent = out;
        }, 34);
      }
      timer.hidden = false;
      bar.style.animation = "none";
      void bar.offsetWidth;
      bar.style.animation = "";
      hideT = setTimeout(function(){ if (!root.isConnected) return; conceal(); }, 8000);
    }
    eye.addEventListener("click", function(){
      if (eye.getAttribute("aria-pressed") === "true") conceal(); else reveal();
    });
    copy.addEventListener("click", function(){
      try { if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(real); } catch (e) {}
      copy.textContent = "Copied";
      copy.classList.add("mds-key-reveal__copy--ok");
      if (copyT) clearTimeout(copyT);
      copyT = setTimeout(function(){
        if (!root.isConnected) return;
        copy.textContent = "Copy";
        copy.classList.remove("mds-key-reveal__copy--ok");
      }, 1300);
    });
    conceal();
  })(rows[r]);
}

css:
.mds-integrations{box-sizing:border-box;background:#0E1118;border:1px solid rgba(255,255,255,.07);border-radius:14px;padding:13px 12px 6px;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#E8EBF4;}
.mds-integrations *{box-sizing:border-box;}
.mds-integrations__head{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:0 2px 8px;}
.mds-integrations__title{margin:0;font-size:13px;font-weight:650;}
.mds-integrations__n{font-size:10.5px;color:#7B849B;font-variant-numeric:tabular-nums;}
.mds-integrations__list{list-style:none;margin:0;padding:0;}
.mds-integrations__row{display:grid;grid-template-columns:28px minmax(0,1fr) auto;grid-template-areas:"tile text pill" "tile act act";align-items:center;gap:3px 9px;padding:9px 2px;border-top:1px solid rgba(255,255,255,.055);}
.mds-integrations__tile{grid-area:tile;display:grid;place-items:center;width:28px;height:28px;border-radius:9px;background:color-mix(in srgb,var(--mds-c) 22%,transparent);border:1px solid color-mix(in srgb,var(--mds-c) 45%,transparent);color:var(--mds-c);font-size:10.5px;font-weight:700;letter-spacing:.2px;}
