.mds-integrations__sub{font-size:10px;color:#6E7791;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.mds-integrations__pill{grid-area:pill;display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:999px;font-size:9.5px;font-weight:640;letter-spacing:.3px;border:1px solid rgba(255,255,255,.1);color:#8891A7;background:rgba(255,255,255,.04);white-space:nowrap;}
.mds-integrations__dot{width:5px;height:5px;border-radius:50%;background:currentColor;}
.mds-integrations__row[data-state="on"] .mds-integrations__pill{color:#42D6A8;border-color:rgba(66,214,168,.3);background:rgba(66,214,168,.1);}
.mds-integrations__row[data-state="warn"] .mds-integrations__pill{color:#F0B54C;border-color:rgba(240,181,76,.32);background:rgba(240,181,76,.1);}
.mds-integrations__row[data-state="busy"] .mds-integrations__pill{color:#6E9BFF;border-color:rgba(110,155,255,.32);background:rgba(110,155,255,.1);}
.mds-integrations__row[data-state="busy"] .mds-integrations__dot{border-radius:50%;background:none;border:1.4px solid currentColor;border-top-color:transparent;width:9px;height:9px;animation:mds-integrations-spin .7s linear infinite;}
.mds-integrations__row[data-state="warn"] .mds-integrations__dot{animation:mds-integrations-pulse 1.6s ease-in-out infinite;}
.mds-integrations__row[data-state="warn"] .mds-integrations__sub{color:#C39A4E;}
.mds-integrations__act{grid-area:act;justify-self:start;margin-top:3px;padding:4px 10px;border-radius:7px;border:1px solid rgba(255,255,255,.13);background:transparent;font:inherit;font-size:10.5px;font-weight:560;color:#C3CADA;cursor:pointer;transition:background .16s ease,border-color .16s ease,opacity .16s ease;}
.mds-integrations__act:hover:not(:disabled){background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.24);}
.mds-integrations__act:focus-visible{outline:2px solid #6E9BFF;outline-offset:2px;}
.mds-integrations__row[data-state="busy"] .mds-integrations__act{color:#8891A7;border-style:dashed;}
.mds-integrations__row[data-state="off"] .mds-integrations__act{color:#0C1016;border-color:transparent;background:linear-gradient(180deg,#E9EDF7,#BFC7DA);}
.mds-integrations__row[data-state="warn"] .mds-integrations__act{color:#F0B54C;border-color:rgba(240,181,76,.42);}
@keyframes mds-integrations-spin{to{transform:rotate(360deg);}}
@keyframes mds-integrations-pulse{0%,100%{opacity:1;}50%{opacity:.25;}}
@media (prefers-reduced-motion: reduce){
.mds-integrations__row[data-state="busy"] .mds-integrations__dot{animation:none;}
.mds-integrations__row[data-state="warn"] .mds-integrations__dot{animation:none;}
.mds-integrations__act{transition:none;}
}

js:
var rows = root.querySelectorAll(".mds-integrations__row");
var tally = root.querySelector(".mds-integrations__n");
var LABEL = {on: "Connected", off: "Not connected", warn: "Action needed", busy: "Connecting"};
var ACTION = {on: "Disconnect", off: "Connect", warn: "Reauthorize", busy: "Cancel"};
function count(){
  var n = 0;
  for (var i = 0; i < rows.length; i++){ if (rows[i].getAttribute("data-state") === "on") n++; }
  tally.textContent = n + " connected";
}
function render(row){
  var st = row.getAttribute("data-state");
  row.querySelector(".mds-integrations__state").textContent = LABEL[st];
  row.querySelector(".mds-integrations__act").textContent = ACTION[st];
  var sub = row.querySelector(".mds-integrations__sub");
  if (st === "warn") sub.textContent = row.getAttribute("data-warn");
  else if (st === "busy") sub.textContent = "Awaiting authorisation";
  else sub.textContent = row.getAttribute("data-sub");
  count();
}
for (var r = 0; r < rows.length; r++){
  (function(row){
    var act = row.querySelector(".mds-integrations__act");
    var pending = null, prev = null;
    act.addEventListener("click", function(){
      var st = row.getAttribute("data-state");
      if (st === "busy"){
        if (pending){ clearTimeout(pending); pending = null; }
        row.setAttribute("data-state", prev || "off");
        render(row);
        return;
      }
      if (st === "on"){ row.setAttribute("data-state", "off"); render(row); return; }
      prev = st;
      row.setAttribute("data-state", "busy");
      render(row);
      pending = setTimeout(function(){
        if (!root.isConnected) return;
        pending = null;
        row.setAttribute("data-state", "on");
        render(row);
      }, 950);
    });
    render(row);
  })(rows[r]);
}
